// Construye dinámicamente las URLs de Google News RSS y blogs opcionales
// a partir del nodo "Configuración del Radar".
const config = $input.first().json;
const region = config.region || { hl: 'es-419', gl: 'AR', ceid: 'AR:es-419' };

function buildGoogleNewsUrl(query) {
  const params = [
    'q=' + encodeURIComponent(query),
    'hl=' + encodeURIComponent(region.hl || 'es-419'),
    'gl=' + encodeURIComponent(region.gl || 'AR'),
    'ceid=' + encodeURIComponent(region.ceid || 'AR:es-419'),
  ].join('&');
  return 'https://news.google.com/rss/search?' + params;
}

const feeds = [];

for (const comp of config.competitors || []) {
  if (comp.query && comp.query.trim()) {
    feeds.push({
      json: {
        source_type: 'competitor',
        entity: comp.name,
        feed_label: 'Google News · ' + comp.name,
        feed_url: buildGoogleNewsUrl(comp.query.trim()),
        config,
      },
    });
  }
  if (comp.blog_rss && comp.blog_rss.trim()) {
    feeds.push({
      json: {
        source_type: 'competitor',
        entity: comp.name,
        feed_label: 'Blog Oficial · ' + comp.name,
        feed_url: comp.blog_rss.trim(),
        config,
      },
    });
  }
}

for (const kw of config.sector_keywords || []) {
  if (kw.query && kw.query.trim()) {
    feeds.push({
      json: {
        source_type: 'sector',
        entity: kw.name,
        feed_label: 'Sector · ' + kw.name,
        feed_url: buildGoogleNewsUrl(kw.query.trim()),
        config,
      },
    });
  }
}

if (feeds.length === 0) {
  throw new Error('No hay competidores ni keywords configurados en "Configuración del Radar".');
}

return feeds;

// Parsea RSS 2.0 / Atom, normaliza URLs y títulos, calcula SHA-256 puro
// (sin require('crypto') para máxima portabilidad) y filtra duplicados
// leyendo Static Data SIN mutarlo todavía (el commit ocurre tras enviar Gmail).

const rawResponses = $input.all();
const sourceItems = $('Generar Fuentes RSS').all();
const config = sourceItems[0]?.json?.config || {};

const now = new Date();
const nowMs = now.getTime();
const nowIso = now.toISOString();
const isMonday = now.getDay() === 1;
const windowHours = isMonday
  ? Number(config.monday_freshness_hours || 72)
  : Number(config.freshness_hours || 24);
const cutoffMs = nowMs - windowHours * 3600 * 1000;

const dedupTtlDays = Number(config.dedup_ttl_days || 30);
const dedupCutoffMs = nowMs - dedupTtlDays * 24 * 3600 * 1000;
const memoryTtlDays = Number(config.memory_ttl_days || 14);
const memoryCutoffMs = nowMs - memoryTtlDays * 24 * 3600 * 1000;
const maxPerSource = Number(config.max_items_per_source || 6);
const maxTotal = Number(config.max_total_items_for_llm || 24);

// --- SHA-256 puro en JS (FIPS 180-4, compatible con UTF-8, sin módulos Node) ---
const SHA256_K = [
  0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
  0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
  0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
  0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
  0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
  0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
  0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
  0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
];

function toUtf8Bytes(str) {
  const bytes = [];
  for (let i = 0; i < str.length; i++) {
    let c = str.charCodeAt(i);
    if (c >= 0xd800 && c <= 0xdbff && i + 1 < str.length) {
      const next = str.charCodeAt(i + 1);
      if (next >= 0xdc00 && next <= 0xdfff) {
        c = 0x10000 + ((c - 0xd800) << 10) + (next - 0xdc00);
        i++;
      }
    }
    if (c < 0x80) bytes.push(c);
    else if (c < 0x800) bytes.push(0xc0 | (c >> 6), 0x80 | (c & 0x3f));
    else if (c < 0x10000) bytes.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 0x3f), 0x80 | (c & 0x3f));
    else bytes.push(0xf0 | (c >> 18), 0x80 | ((c >> 12) & 0x3f), 0x80 | ((c >> 6) & 0x3f), 0x80 | (c & 0x3f));
  }
  return bytes;
}

function sha256(str) {
  const bytes = toUtf8Bytes(String(str));
  const bitLen = bytes.length * 8;
  bytes.push(0x80);
  while ((bytes.length % 64) !== 56) bytes.push(0);
  const hiBits = Math.floor(bitLen / 0x100000000);
  const loBits = bitLen >>> 0;
  bytes.push(
    (hiBits >>> 24) & 0xff, (hiBits >>> 16) & 0xff, (hiBits >>> 8) & 0xff, hiBits & 0xff,
    (loBits >>> 24) & 0xff, (loBits >>> 16) & 0xff, (loBits >>> 8) & 0xff, loBits & 0xff
  );

  let h0 = 0x6a09e667, h1 = 0xbb67ae85, h2 = 0x3c6ef372, h3 = 0xa54ff53a;
  let h4 = 0x510e527f, h5 = 0x9b05688c, h6 = 0x1f83d9ab, h7 = 0x5be0cd19;
  const w = new Array(64);

  for (let offset = 0; offset < bytes.length; offset += 64) {
    for (let i = 0; i < 16; i++) {
      w[i] = ((bytes[offset + i * 4] << 24) | (bytes[offset + i * 4 + 1] << 16) |
              (bytes[offset + i * 4 + 2] << 8) | bytes[offset + i * 4 + 3]) >>> 0;
    }
    for (let i = 16; i < 64; i++) {
      const s0 = ((w[i - 15] >>> 7) | (w[i - 15] << 25)) ^ ((w[i - 15] >>> 18) | (w[i - 15] << 14)) ^ (w[i - 15] >>> 3);
      const s1 = ((w[i - 2] >>> 17) | (w[i - 2] << 15)) ^ ((w[i - 2] >>> 19) | (w[i - 2] << 13)) ^ (w[i - 2] >>> 10);
      w[i] = (w[i - 16] + s0 + w[i - 7] + s1) >>> 0;
    }
    let a = h0, b = h1, c = h2, d = h3, e = h4, f = h5, g = h6, h = h7;
    for (let i = 0; i < 64; i++) {
      const S1 = ((e >>> 6) | (e << 26)) ^ ((e >>> 11) | (e << 21)) ^ ((e >>> 25) | (e << 7));
      const ch = (e & f) ^ (~e & g);
      const temp1 = (h + S1 + ch + SHA256_K[i] + w[i]) >>> 0;
      const S0 = ((a >>> 2) | (a << 30)) ^ ((a >>> 13) | (a << 19)) ^ ((a >>> 22) | (a << 10));
      const maj = (a & b) ^ (a & c) ^ (b & c);
      const temp2 = (S0 + maj) >>> 0;
      h = g; g = f; f = e; e = (d + temp1) >>> 0;
      d = c; c = b; b = a; a = (temp1 + temp2) >>> 0;
    }
    h0 = (h0 + a) >>> 0; h1 = (h1 + b) >>> 0; h2 = (h2 + c) >>> 0; h3 = (h3 + d) >>> 0;
    h4 = (h4 + e) >>> 0; h5 = (h5 + f) >>> 0; h6 = (h6 + g) >>> 0; h7 = (h7 + h) >>> 0;
  }

  return [h0, h1, h2, h3, h4, h5, h6, h7]
    .map((v) => v.toString(16).padStart(8, '0'))
    .join('');
}

// --- Helpers de parsing XML (RSS 2.0 + Atom) y normalización ---
function decodeEntities(text) {
  if (!text) return '';
  return String(text)
    .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1')
    .replace(/&#x([0-9a-fA-F]+);/g, (_, hex) => String.fromCodePoint(parseInt(hex, 16)))
    .replace(/&#(\d+);/g, (_, dec) => String.fromCodePoint(parseInt(dec, 10)))
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/&#39;/g, "'")
    .replace(/&nbsp;/g, ' ')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&amp;/g, '&');
}

function stripHtml(text) {
  return decodeEntities(text)
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function extractTag(block, tagName) {
  const regex = new RegExp('<' + tagName + '(?:\\s[^>]*)?>([\\s\\S]*?)</' + tagName + '>', 'i');
  const match = block.match(regex);
  return match ? decodeEntities(match[1]).trim() : '';
}

function extractAtomLink(block) {
  const alt = block.match(/<link[^>]*rel=["']alternate["'][^>]*href=["']([^"']+)["'][^>]*\/?>/i);
  if (alt) return decodeEntities(alt[1]).trim();
  const anyHref = block.match(/<link[^>]*href=["']([^"']+)["'][^>]*\/?>/i);
  if (anyHref) return decodeEntities(anyHref[1]).trim();
  return extractTag(block, 'link');
}

function parseFeedXml(xml) {
  if (!xml || typeof xml !== 'string') return [];
  const entries = [];
  const rssMatches = xml.match(/<item(?:\s[^>]*)?>[\s\S]*?<\/item>/gi) || [];
  for (const block of rssMatches) {
    entries.push({
      title: stripHtml(extractTag(block, 'title')),
      link: extractTag(block, 'link'),
      guid: extractTag(block, 'guid'),
      pubDate: extractTag(block, 'pubDate') || extractTag(block, 'dc:date'),
      description: stripHtml(extractTag(block, 'description')),
      publisher: stripHtml(extractTag(block, 'source')),
    });
  }
  if (entries.length === 0) {
    const atomMatches = xml.match(/<entry(?:\s[^>]*)?>[\s\S]*?<\/entry>/gi) || [];
    for (const block of atomMatches) {
      entries.push({
        title: stripHtml(extractTag(block, 'title')),
        link: extractAtomLink(block),
        guid: extractTag(block, 'id'),
        pubDate: extractTag(block, 'published') || extractTag(block, 'updated'),
        description: stripHtml(extractTag(block, 'summary') || extractTag(block, 'content')),
        publisher: stripHtml(extractTag(block, 'name')),
      });
    }
  }
  return entries;
}

const TRACKING_PARAMS = new Set([
  'fbclid', 'gclid', 'dclid', 'msclkid', 'mc_cid', 'mc_eid', 'ref', 'ref_src', 'oc', 'spm', 'igshid',
]);

function normalizeUrl(rawUrl) {
  if (!rawUrl) return '';
  try {
    const parsed = new URL(rawUrl.trim());
    parsed.hostname = parsed.hostname.toLowerCase();
    parsed.hash = '';
    for (const key of [...parsed.searchParams.keys()]) {
      if (key.toLowerCase().startsWith('utm_') || TRACKING_PARAMS.has(key.toLowerCase())) {
        parsed.searchParams.delete(key);
      }
    }
    parsed.searchParams.sort();
    let result = parsed.toString();
    if (result.endsWith('/') && parsed.pathname !== '/') {
      result = result.slice(0, -1);
    }
    return result;
  } catch {
    return rawUrl.trim();
  }
}

function normalizeTitleForFingerprint(rawTitle) {
  if (!rawTitle) return '';
  // Quita el sufijo de medio típico de Google News ("Titular - Infobae")
  const withoutPublisher = rawTitle.replace(/\s+[-–—|]\s+[^-–—|]{2,45}$/, '');
  return withoutPublisher
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

// --- Lectura de estado previo (SOLO LECTURA) ---
const staticData = $getWorkflowStaticData('global');
const activeSeenHashes = new Set();
const activeSeenTitles = new Set();

for (const [h, isoDate] of Object.entries(staticData.seen_hashes || {})) {
  const ts = Date.parse(isoDate);
  if (!Number.isNaN(ts) && ts >= dedupCutoffMs) activeSeenHashes.add(h);
}
for (const [th, isoDate] of Object.entries(staticData.seen_titles || {})) {
  const ts = Date.parse(isoDate);
  if (!Number.isNaN(ts) && ts >= dedupCutoffMs) activeSeenTitles.add(th);
}

const recentEvents = (Array.isArray(staticData.recent_events) ? staticData.recent_events : [])
  .filter((ev) => {
    const ts = Date.parse(ev.recorded_at || ev.date || '');
    return !Number.isNaN(ts) && ts >= memoryCutoffMs;
  })
  .slice(-Number(config.memory_max_events || 30));

// --- Procesamiento y deduplicación ---
const failedSources = [];
const intraByHash = new Map();
const intraByTitle = new Map();
const perSourceCount = new Map();

let totalScanned = 0;
let filteredByAge = 0;
let filteredHistoricalDupes = 0;
let filteredIntraRunDupes = 0;

for (let i = 0; i < rawResponses.length; i++) {
  const resp = rawResponses[i]?.json || {};
  const meta = sourceItems[i]?.json || {
    source_type: 'sector',
    entity: 'Fuente #' + (i + 1),
    feed_label: 'Feed #' + (i + 1),
    feed_url: '',
  };

  const xml = typeof resp.raw_xml === 'string'
    ? resp.raw_xml
    : (typeof resp.data === 'string' ? resp.data : '');

  if (!xml || resp.error) {
    failedSources.push({
      feed_label: meta.feed_label,
      entity: meta.entity,
      reason: resp.error ? String(resp.error.message || resp.error) : 'Respuesta XML vacía',
    });
    continue;
  }

  const parsedEntries = parseFeedXml(xml);
  for (const entry of parsedEntries) {
    totalScanned++;
    if (!entry.title) continue;

    const pubMs = Date.parse(entry.pubDate || '');
    if (!Number.isNaN(pubMs) && pubMs < cutoffMs) {
      filteredByAge++;
      continue;
    }

    const cleanUrl = normalizeUrl(entry.link);
    const idSeed = cleanUrl || (entry.guid || '').trim() || entry.title;
    const articleHash = sha256(idSeed);

    const normTitle = normalizeTitleForFingerprint(entry.title);
    const titleHash = normTitle.length >= 20 ? sha256(normTitle) : '';

    // 1. Deduplicación histórica contra Static Data
    if (activeSeenHashes.has(articleHash) || (titleHash && activeSeenTitles.has(titleHash))) {
      filteredHistoricalDupes++;
      continue;
    }

    // 2. Deduplicación intra-corrida (fusiona entidades si coincide en dos queries)
    const existing = intraByHash.get(articleHash) || (titleHash ? intraByTitle.get(titleHash) : null);
    if (existing) {
      filteredIntraRunDupes++;
      if (!existing.matched_entities.includes(meta.entity)) {
        existing.matched_entities.push(meta.entity);
      }
      if (meta.source_type === 'competitor') {
        existing.source_type = 'competitor';
      }
      continue;
    }

    // Límite por fuente para mantener equilibrio y controlar tokens
    const countForFeed = perSourceCount.get(meta.feed_label) || 0;
    if (countForFeed >= maxPerSource) continue;
    perSourceCount.set(meta.feed_label, countForFeed + 1);

    const publisher = entry.publisher || (entry.title.includes(' - ') ? entry.title.split(' - ').pop().trim() : 'Fuente RSS');
    const cleanTitle = entry.title.replace(/\s+-\s+[^-]{2,45}$/, '').trim();

    const article = {
      article_hash: articleHash,
      title_hash: titleHash,
      source_type: meta.source_type,
      entity: meta.entity,
      matched_entities: [meta.entity],
      feed_label: meta.feed_label,
      title: cleanTitle || entry.title,
      snippet: (entry.description || '').slice(0, 320),
      publisher,
      url: cleanUrl || entry.link || '',
      published_at: !Number.isNaN(pubMs) ? new Date(pubMs).toISOString() : nowIso,
      published_ms: !Number.isNaN(pubMs) ? pubMs : nowMs,
    };

    intraByHash.set(articleHash, article);
    if (titleHash) intraByTitle.set(titleHash, article);
  }
}

// Ordena por prioridad (competidores primero dentro de frescura similar) y recencia
const allNewArticles = [...intraByHash.values()]
  .sort((a, b) => b.published_ms - a.published_ms)
  .slice(0, maxTotal);

const pendingHashes = {};
const pendingTitleHashes = {};
for (const art of allNewArticles) {
  pendingHashes[art.article_hash] = nowIso;
  if (art.title_hash) pendingTitleHashes[art.title_hash] = nowIso;
}

return [
  {
    json: {
      has_new_items: allNewArticles.length > 0,
      new_items_count: allNewArticles.length,
      articles: allNewArticles,
      pending_hashes: pendingHashes,
      pending_title_hashes: pendingTitleHashes,
      recent_events: recentEvents,
      failed_sources: failedSources,
      run_metadata: {
        run_date_iso: nowIso,
        run_date_ymd: nowIso.slice(0, 10),
        window_hours: windowHours,
        is_monday_extended_window: isMonday,
        new_items_count: allNewArticles.length,
        sources_checked: sourceItems.length,
        sources_failed: failedSources.length,
        total_scanned: totalScanned,
        filtered_by_age: filteredByAge,
        filtered_historical_duplicates: filteredHistoricalDupes,
        filtered_intra_run_duplicates: filteredIntraRunDupes,
        active_historical_hashes: activeSeenHashes.size,
        active_memory_events: recentEvents.length,
      },
      config,
    },
  },
];

// Construye el payload oficial de Gemini API con salida JSON estructurada
// (responseMimeType + responseJsonSchema) y memoria histórica comparativa.

const data = $input.first().json;
const { articles = [], recent_events = [], config = {}, run_metadata = {} } = data;

const systemInstruction = [
  'Eres un analista senior de inteligencia competitiva especializado en E-commerce y Retail para empresas medianas en Latinoamérica.',
  'Tu objetivo es transformar noticias nuevas en un reporte diario ejecutivo, veraz y accionable en español.',
  '',
  'Reglas estrictas:',
  '1. No inventes hechos, cifras ni URLs. Toda URL incluida en tu respuesta debe copiarse exactamente de NOTICIAS_NUEVAS_HOY.',
  '2. Sé claro, conciso y enfocado en impacto real de negocio (Dirección, Comercial, Marketing, Operaciones, Producto).',
  '3. Sección cambios_relevantes (detección de delta frente al historial):',
  '   - Compara NOTICIAS_NUEVAS_HOY contra HISTORIAL_RECIENTE.',
  '   - Agrega elementos SOLO si detectas un cambio o evolución verdaderamente relevante (ej. cambio de precios/comisiones, paso de rumor a lanzamiento oficial, reversión, escalada o tendencia acelerada frente a días previos).',
  '   - Si no hay historial previo o no hay cambios relevantes, devuelve cambios_relevantes como arreglo vacío []. Nunca inventes ni fuerces comparaciones.',
  '4. Sección eventos_para_memoria:',
  '   - Extrae entre 1 y 8 hechos compactos (1 oración corta cada uno) con lo más importante de hoy para almacenarlo en la memoria de los próximos 14 días.',
  '5. Descarta ruido, notas promocionales sin sustancia o duplicados temáticos.',
].join('\n');

const historyBlock = recent_events.length > 0
  ? recent_events
      .map((ev) => '- [' + (ev.date || 'reciente') + '] [' + ev.entidad + ' | ' + ev.categoria + '] ' + ev.hecho)
      .join('\n')
  : 'Sin historial previo (primera ejecución o sin eventos recientes en los últimos ' + (config.memory_ttl_days || 14) + ' días).';

const newsBlock = articles
  .map((a, idx) => {
    const entities = (a.matched_entities || [a.entity]).join(', ');
    return [
      '[' + (idx + 1) + '] Tipo: ' + a.source_type + ' | Entidad(es): ' + entities + ' | Medio: ' + a.publisher + ' | Fecha: ' + a.published_at,
      'Titular: ' + a.title,
      a.snippet ? 'Extracto: ' + a.snippet : '',
      'URL: ' + a.url,
    ].filter(Boolean).join('\n');
  })
  .join('\n\n');

const userPrompt = [
  'Fecha del reporte: ' + (run_metadata.run_date_ymd || new Date().toISOString().slice(0, 10)),
  'Ventana analizada: últimas ' + (run_metadata.window_hours || 24) + ' horas.',
  '',
  '=== HISTORIAL_RECIENTE (últimos ' + (config.memory_ttl_days || 14) + ' días) ===',
  historyBlock,
  '',
  '=== NOTICIAS_NUEVAS_HOY (' + articles.length + ' artículos deduplicados) ===',
  newsBlock,
].join('\n');

const responseJsonSchema = {
  type: 'object',
  properties: {
    asunto_email: {
      type: 'string',
      description: 'Asunto ejecutivo conciso (máx 85 caracteres) resumiendo la señal clave del día.',
    },
    resumen_ejecutivo: {
      type: 'string',
      description: 'Resumen de 2 a 3 oraciones con las conclusiones clave del día.',
    },
    cambios_relevantes: {
      type: 'array',
      description: 'Solo cambios o evoluciones materiales detectadas frente al historial reciente. Vacío [] si no hay.',
      items: {
        type: 'object',
        properties: {
          titulo: { type: 'string' },
          entidad: { type: 'string' },
          tipo_cambio: {
            type: 'string',
            enum: ['Escalación', 'Lanzamiento confirmado', 'Cambio de pricing', 'Reversión', 'Tendencia acelerada', 'Actualización clave'],
          },
          urgencia: {
            type: 'string',
            enum: ['alta', 'media'],
          },
