const parts = geminiResponse?.candidates?.[0]?.content?.parts || [];
const rawText = parts.map((p) => p.text || '').join('').trim();

if (!rawText) {
  throw new Error('La respuesta de Gemini llegó vacía o sin candidates[0].content.parts.');
}

const cleanedJson = rawText
  .replace(/^\s*```(?:json)?\s*/i, '')
  .replace(/\s*```\s*$/i, '')
  .trim();

let report;
try {
  report = JSON.parse(cleanedJson);
} catch (err) {
  throw new Error('No se pudo parsear el JSON devuelto por Gemini: ' + err.message);
}

function escapeHtml(str) {
  return String(str ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function safeUrl(url) {
  try {
    const parsed = new URL(String(url || '').trim());
    if (parsed.protocol === 'http:' || parsed.protocol === 'https:') {
      return parsed.toString();
    }
    return '';
  } catch {
    return '';
  }
}

