// Se ejecuta ÚNICAMENTE después de que Gmail confirma el envío del correo.
// Garantiza idempotencia real: si Gemini o Gmail fallan, las noticias no se marcan como vistas.

const gmailResult = $input.first().json || {};
const payload = $('Parsear Respuesta y Generar Email HTML').first().json;
const {
  pending_hashes = {},
  pending_title_hashes = {},
  eventos_para_memoria = [],
  changes_detected_count = 0,
  config = {},
  run_metadata = {},
} = payload;

const now = new Date();
const nowMs = now.getTime();
const nowIso = now.toISOString();
const runDateYmd = run_metadata.run_date_ymd || nowIso.slice(0, 10);

const dedupCutoffMs = nowMs - Number(config.dedup_ttl_days || 30) * 24 * 3600 * 1000;
const memoryCutoffMs = nowMs - Number(config.memory_ttl_days || 14) * 24 * 3600 * 1000;
const memoryMaxEvents = Number(config.memory_max_events || 30);

const staticData = $getWorkflowStaticData('global');

// 1. Merge y poda de seen_hashes (TTL 30 días)
const mergedHashes = { ...(staticData.seen_hashes || {}), ...pending_hashes };
const prunedHashes = {};
for (const [h, iso] of Object.entries(mergedHashes)) {
  const ts = Date.parse(iso);
  if (!Number.isNaN(ts) && ts >= dedupCutoffMs) {
    prunedHashes[h] = iso;
  }
}

// 2. Merge y poda de seen_titles (TTL 30 días)
const mergedTitles = { ...(staticData.seen_titles || {}), ...pending_title_hashes };
const prunedTitles = {};
for (const [th, iso] of Object.entries(mergedTitles)) {
  const ts = Date.parse(iso);
  if (!Number.isNaN(ts) && ts >= dedupCutoffMs) {
    prunedTitles[th] = iso;
  }
}

// 3. Append y poda de recent_events (memoria comparativa de 14 días)
const prevEvents = Array.isArray(staticData.recent_events) ? staticData.recent_events : [];
const newEvents = (Array.isArray(eventos_para_memoria) ? eventos_para_memoria : [])
  .filter((ev) => ev && ev.hecho)
  .map((ev) => ({
    date: runDateYmd,
    recorded_at: nowIso,
    entidad: String(ev.entidad || 'Sector'),
    categoria: String(ev.categoria || 'General'),
    hecho: String(ev.hecho).slice(0, 240),
  }));

const prunedEvents = [...prevEvents, ...newEvents]
  .filter((ev) => {
    const ts = Date.parse(ev.recorded_at || ev.date || '');
    return !Number.isNaN(ts) && ts >= memoryCutoffMs;
  })
  .slice(-memoryMaxEvents);

// 4. Commit atómico en Static Data
staticData.seen_hashes = prunedHashes;
staticData.seen_titles = prunedTitles;
staticData.recent_events = prunedEvents;
staticData.last_successful_run = {
  timestamp: nowIso,
  gmail_message_id: gmailResult.id || gmailResult.messageId || null,
  new_items_sent: Number(run_metadata.new_items_count || Object.keys(pending_hashes).length),
  changes_detected: Number(changes_detected_count || 0),
};

return [
  {
    json: {
      status: 'committed',
      sent_to: payload.email_to,
      subject: payload.email_subject,
      gmail_message_id: gmailResult.id || gmailResult.messageId || null,
      committed_hashes: Object.keys(pending_hashes).length,
      total_active_hashes: Object.keys(prunedHashes).length,
      total_active_title_fingerprints: Object.keys(prunedTitles).length,
      memory_events_added: newEvents.length,
      total_active_memory_events: prunedEvents.length,
      changes_detected: Number(changes_detected_count || 0),
      committed_at: nowIso,
    },
  },
];
